#233;nite.html&quot; title=&quot;&#201;cu en &#233;b&#233;nite&quot;&gt;&#201;cu en &#233;b&#233;nite&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Similaire &#224; un &lt;a class=&quot;pagelink&quot; href=&quot;&#201;cu-(Armure).html&quot; title=&quot;&#201;cu (bois/acier)&quot;&gt;&#233;cu (bois)&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armures#Armuresmaitre.html&quot; title=&quot;armure de ma&#238;tre&quot;&gt;de ma&#238;tre&lt;/a&gt; en &lt;a class=&quot;pagelink&quot; href=&quot;Mat&#233;riaux-Sp&#233;ciaux#Ebenite.html&quot; title=&quot;&#233;b&#233;nite&quot;&gt;&#233;b&#233;nite&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;257 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;cu-En-Mithral.html&quot; title=&quot;&#201;cu en mithral&quot;&gt;&#201;cu en mithral&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Similaire &#224; un &lt;a class=&quot;pagelink&quot; href=&quot;&#201;cu-(Armure).html&quot; title=&quot;&#201;cu (bois/acier)&quot;&gt;&#233;cu (acier)&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armures#Armuresmaitre.html&quot; title=&quot;armure de ma&#238;tre&quot;&gt;de ma&#238;tre&lt;/a&gt; en &lt;a class=&quot;pagelink&quot; href=&quot;Mat&#233;riaux-Sp&#233;ciaux#Mithral.html&quot; title=&quot;mithral&quot;&gt;mithral&lt;/a&gt;. .&lt;/td&gt;&lt;td&gt;1 020 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bouclier-En-Peau-De-Zombi.html&quot; title=&quot;Bouclier en peau de zombi&quot;&gt;Bouclier en peau de zombi&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Similaire &#224; une &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Rondache-(Armure).html&quot; title=&quot;Rondache (bois/acier)&quot;&gt;rondache (acier)&lt;/a&gt; +1&lt;/i&gt;. Une fois par jour, peut g&#233;n&#233;rer un &lt;a class=&quot;pagelink&quot; href=&quot;Zombi-Humain.html&quot; title=&quot;Zombi, Zombi humain&quot;&gt;zombi humain&lt;/a&gt; qui sert fid&#232;lement le porteur (comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Animation-Des-Morts.html&quot; title=&quot;Animation des morts&quot;&gt;animation des morts&lt;/a&gt;&lt;/i&gt;) pendant 5 minutes.&lt;/td&gt;&lt;td&gt;2 159 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bouclier-En-Bois-Flott&#233;.html&quot; title=&quot;Bouclier en bois flott&#233;&quot;&gt;Bouclier en bois flott&#233;&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISG&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Similaire &#224; un &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;cu-(Armure).html&quot; title=&quot;&#201;cu (bois/acier)&quot;&gt;&#233;cu en bois&lt;/a&gt; +1&lt;/i&gt;. Permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Rep&#233;rage.html&quot; title=&quot;Rep&#233;rage&quot;&gt;rep&#233;rage&lt;/a&gt;&lt;/i&gt; &#224; volont&#233;. Une fois par jour, peut lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Distorsion-Du-Bois.html&quot; title=&quot;Distorsion du bois&quot;&gt;distorsion du bois&lt;/a&gt;&lt;/i&gt; sur un objet tenu par un assaillant adverse.&lt;/td&gt;&lt;td&gt;2 517 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bouclier-Des-Arcanes.html&quot; title=&quot;Bouclier des arcanes&quot;&gt;Bouclier des Arcanes&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Similaire &#224; une &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Rondache-(Armure).html&quot; title=&quot;Rondache (bois/acier)&quot;&gt;rondache (bois)&lt;/a&gt; +1&lt;/i&gt;. Un lanceur de sort peut y &#233;crire un &lt;a class=&quot;pagelink&quot; href=&quot;Parchemins-Magiques.html&quot; title=&quot;Les parchemins magiques&quot;&gt;parchemin magique&lt;/a&gt; d’un sort du 3e niveau ou moins pour la moiti&#233; du co&#251;t habituel.&lt;/td&gt;&lt;td&gt;3 153 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bouclier-Du-Chuchoteur-Mordor&#233;.html&quot; title=&quot;Bouclier du chuchoteur mordor&#233;&quot;&gt;Bouclier du chuchoteur mordor&#233;&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISG&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Similaire &#224; une &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Rondache-(Armure).html&quot; title=&quot;Rondache (bois/acier)&quot;&gt;rondace en acier&lt;/a&gt; +1&lt;/i&gt;. Peut prendre la forme d&#39;une &lt;a class=&quot;pagelink&quot; href=&quot;Targe-(Armure).html&quot; title=&quot;Targe&quot;&gt;targe&lt;/a&gt; &#224; volont&#233;. Une fois par jour, peut d&#233;livrer une &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;charge-&#201;lectrique.html&quot; title=&quot;D&#233;charge &#233;lectrique&quot;&gt;d&#233;charge &#233;lectrique&lt;/a&gt;&lt;/i&gt;.&lt;/td&gt;&lt;td&gt;4 279 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Targe-Du-Cambrioleur.html&quot; title=&quot;Targe du cambrioleur&quot;&gt;Targe du Cambrioleur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Similaire &#224; une &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Targe-(Armure).html&quot; title=&quot;Targe&quot;&gt;targe&lt;/a&gt; +1&lt;/i&gt;. Conf&#232;re un bonus de comp&#233;tence de +2 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Sabotage.html&quot; title=&quot;Sabotage&quot;&gt;Sabotage&lt;/a&gt; et d’&lt;a class=&quot;pagelink&quot; href=&quot;Escamotage.html&quot; title=&quot;Escamotage&quot;&gt;Escamotage&lt;/a&gt;, au &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Bmo.html&quot; title=&quot;BMO&quot;&gt;BMO&lt;/a&gt; pour effectuer des manœuvres de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Salecoup.html&quot; title=&quot;sale coup&quot;&gt;sale coup&lt;/a&gt; et au &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Dmd.html&quot; title=&quot;DMD&quot;&gt;DMD&lt;/a&gt; contre cette m&#234;me manœuvre. Une fois par jour, peut se transformer en outil ordinaire, &lt;a class=&quot;pagelink&quot; href=&quot;Trousses%20doutils%20et%20de%20comp%C3%A9tences.ashx#Outils d&#39;artisan&quot; title=&quot;Trousses d’outils et de comp&#233;tences&quot;&gt;d’artisan&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Trousses-Doutils-Et-De-Comp&#233;tences.html#Outils de cambrioleur&quot; title=&quot;Trousses d’outils et de comp&#233;tences&quot;&gt;de cambrioleur&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;4 655 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bouclier-Provoquant.html&quot; title=&quot;Bouclier provoquant&quot;&gt;Bouclier provoquant&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;AMH&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Similaire &#224; un &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;cu-(Armure).html&quot; title=&quot;&#201;cu (bois/acier)&quot;&gt;&#233;cu en acier&lt;/a&gt; +1&lt;/i&gt;. Un porteur avec la capacit&#233; de classe &lt;a class=&quot;pagelink&quot; href=&quot;Chevalier.html#DEFI&quot; title=&quot;Le chevalier&quot;&gt;d&#233;fi&lt;/a&gt; peut en d&#233;penser une utilisation pour ajouter son modificateur de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Le Charisme&quot;&gt;Charisme&lt;/a&gt; &#224; son bonus de bouclier &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt; pendant 1 minute.&lt;/td&gt;&lt;td&gt;5 170 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bouclier-De-La-Manticore.html&quot; title=&quot;Bouclier de la manticore&quot;&gt;Bouclier de la Manticore&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Similaire &#224; un &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;cu-(Armure).html&quot; title=&quot;&#201;cu (bois/acier)&quot;&gt;&#233;cu (acier)&lt;/a&gt; +1&lt;/i&gt;. Trois fois par jour, peut effectuer une attaque d’&#233;pines +1 infligeant 1d10 points de d&#233;g&#226;ts avec un facteur de port&#233;e de 36m et une zone de critique de 19-20.&lt;/td&gt;&lt;td&gt;5 580 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bouclier-Saboteur.html&quot; title=&quot;Bouclier saboteur&quot;&gt;Bouclier saboteur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;UI&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Similaire &#224; une &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Rondache-(Armure).html&quot; title=&quot;Rondache (bois/acier)&quot;&gt;rondache (acier)&lt;/a&gt; +2&lt;/i&gt;. Sur commande, peut effectuer un test de &lt;a class=&quot;pagelink&quot; href=&quot;Sabotage.html&quot; title=&quot;Sabotage&quot;&gt;Sabotage&lt;/a&gt; avec un bonus de +10 sur un m&#233;canisme.&lt;/td&gt;&lt;td&gt;7 159 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bouclier-Du-Pourfendeur-De-Dragons.html&quot; title=&quot;Bouclier du pourfendeur de dragons&quot;&gt;Bouclier du Pourfendeur de Dragons&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Similaire &#224; un &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;cu-(Armure).html&quot; title=&quot;&#201;cu (bois/acier)&quot;&gt;&#233;cu (acier)&lt;/a&gt; +2&lt;/i&gt;. Conf&#232;re un bonus de +2 aux jets de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;R&#233;flexes&quot;&gt;R&#233;flexes&lt;/a&gt; contre les effets dont l’origine ou le rayonnement ne provient pas de l’espace qu’occupe le porteur, et un bonus de moral de +2 aux jets de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt; contre la capacit&#233; &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sence-Terrifiante-(Capacit&#233;).html&quot; title=&quot;Pr&#233;sence terrifiante (Ext)&quot;&gt;pr&#233;sence terrifiante&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;7 170 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bouclier-Griffu.html&quot; title=&quot;Bouclier griffu&quot;&gt;Bouclier Griffu&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Similaire &#224; un &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;cu-(Armure).html&quot; title=&quot;&#201;cu (bois/acier)&quot;&gt;&#233;cu (acier)&lt;/a&gt; +2 en &lt;a class=&quot;pagelink&quot; href=&quot;Mat&#233;riaux-Sp&#233;ciaux#Mithral.html&quot; title=&quot;mithral&quot;&gt;mithral&lt;/a&gt;&lt;/i&gt;, mais n’est pas consid&#233;r&#233; comme un objet m&#233;tallique. Lorsque le porteur est &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Agripp&#233;.html&quot; title=&quot;Agripp&#233;&quot;&gt;agripp&#233;&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Immobilis&#233;.html&quot; title=&quot;Immobilis&#233;&quot;&gt;immobilis&#233;&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Engloutissement-(Capacit&#233;).html&quot; title=&quot;Engloutissement (Ext)&quot;&gt;englouti&lt;/a&gt;, peut effectuer une attaque au corps &#224; corps infligeant 1d8 + le modificateur de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Force.html&quot; title=&quot;La Force&quot;&gt;Force&lt;/a&gt; du porteur points de d&#233;g&#226;ts ou effectuer la composante gestuelle d’un sort que le porteur souhaite incanter &#224; sa place.&lt;/td&gt;&lt;td&gt;8 158 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pavois-Pliant.html&quot; title=&quot;Pavois pliant&quot;&gt;Pavois Pliant&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Similaire &#224; un &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;cu-(Armure).html&quot; title=&quot;&#201;cu (bois/acier)&quot;&gt;&#233;cu (acier)&lt;/a&gt; +2&lt;/i&gt;. Trois fois par jour, peut se transformer en &lt;a class=&quot;pagelink&quot; href=&quot;Pavois-(Armure).html&quot; title=&quot;Pavois&quot;&gt;pavois&lt;/a&gt; +2 pendant 1 minute maximum.&lt;/td&gt;&lt;td&gt;8 170 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bouclier-Du-Lion.html&quot; title=&quot;Bouclier du lion&quot;&gt;Bouclier du Lion&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Similaire &#224; un &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;cu-(Armure).html&quot; title=&quot;&#201;cu (bois/acier)&quot;&gt;&#233;cu (acier)&lt;/a&gt; +2&lt;/i&gt;. Trois fois par jour, peut effectuer une attaque de morsure infligeant 2d6 points de d&#233;g&#226;ts contre une cr&#233;ature adjacente au porteur en utilisant le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Bonusdebasealattaque.html&quot; title=&quot;BBA&quot;&gt;BBA&lt;/a&gt; de ce dernier.&lt;/td&gt;&lt;td&gt;9 170 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bouclier-Des-Arcanes-Supr&#234;me.html&quot; title=&quot;Bouclier des arcanes supr&#234;me&quot;&gt;Bouclier des Arcanes Supr&#234;me&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Similaire &#224; une &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Rondache-(Armure).html&quot; title=&quot;Rondache (bois/acier)&quot;&gt;rondache (bois)&lt;/a&gt; +3&lt;/i&gt;. Un lanceur de sort peut y &#233;crire un &lt;a class=&quot;pagelink&quot; href=&quot;Parchemins-Magiques.html&quot; title=&quot;Les parchemins magiques&quot;&gt;parchemin magique&lt;/a&gt; d’un sort du 5e niveau ou moins pour la moiti&#233; du co&#251;t habituel..&lt;/td&gt;&lt;td&gt;10 153 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Targe-Dartilleur.html&quot; title=&quot;Targe d&amp;#39;artilleur&quot;&gt;Targe d&#39;artilleur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;AMH&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Similaire &#224; une &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Targe-(Armure).html&quot; title=&quot;Targe&quot;&gt;targe&lt;/a&gt; +1 en &lt;a class=&quot;pagelink&quot; href=&quot;Mat&#233;riaux-Sp&#233;ciaux#Mithral.html&quot; title=&quot;mithral&quot;&gt;mithral&lt;/a&gt;&lt;/i&gt;. Le porteur ne provoque pas d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Attaquedopportunite.html&quot; title=&quot;Attaque d&amp;#39;opportunit&#233; (redirection)&quot;&gt;attaques d&#39;opportunit&#233;&lt;/a&gt; lorsqu&#39;il utilise une arme &#224; feu dans une zone contr&#244;l&#233;e au corps &#224; corps, mais subit un malus de -4 &#224; l&#39;attaque.&lt;/td&gt;&lt;td&gt;10 155 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Croc-Du-R&#244;deur.html&quot; title=&quot;Croc du r&#244;deur&quot;&gt;Croc du r&#244;deur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Similaire &#224; un &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Klar-(Armure).html&quot; title=&quot;Klar&quot;&gt;klar&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armes#Ac&#233;r&#233;e.html&quot; title=&quot;ac&#233;r&#233;e (propri&#233;t&#233;)&quot;&gt;ac&#233;r&#233;&lt;/a&gt; +1&lt;/i&gt;. Le bonus d&#39;alt&#233;ration s&#39;applique aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jets d&#39;attaque&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#DEGATS&quot; title=&quot;Valeurs de combat&quot;&gt;de d&#233;g&#226;ts&lt;/a&gt; de la lame ainsi qu&#39;au bonus de bouclier. Les &lt;a class=&quot;pagelink&quot; href=&quot;Actions-Simples#Coupcritique.html&quot; title=&quot;coup critique&quot;&gt;coups critiques&lt;/a&gt; infligent des d&#233;g&#226;ts de &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Saignement.html&quot; title=&quot;Saignement&quot;&gt;saignement&lt;/a&gt; aux cibles priv&#233;es de leur bonus de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Dexterite.html&quot; title=&quot;Dex&quot;&gt;Dex&lt;/a&gt; &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;11 462 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bouclier-C&#233;leste.html&quot; title=&quot;Bouclier c&#233;leste&quot;&gt;Bouclier C&#233;leste&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E, MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Similaire &#224; un &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;cu-(Armure).html&quot; title=&quot;&#201;cu (bois/acier)&quot;&gt;&#233;cu (acier)&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Aveuglante.html&quot; title=&quot;aveuglante (propri&#233;t&#233;)&quot;&gt;aveuglant&lt;/a&gt; +2&lt;/i&gt;. N’impose aucun malus d’armure aux tests ni de risque d’&#233;chec des sorts profanes. Une fois par jour, peut conf&#233;rer les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Feuille-Morte.html&quot; title=&quot;Feuille morte&quot;&gt;feuille morte&lt;/a&gt;&lt;/i&gt;. Conf&#232;re des pouvoirs sp&#233;ciaux si le porteur poss&#232;de une &lt;a class=&quot;pagelink&quot; href=&quot;Armure-C&#233;leste.html&quot; title=&quot;Armure c&#233;leste&quot;&gt;armure c&#233;leste&lt;/a&gt;. &lt;/td&gt;&lt;td&gt;13 170 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bouclier-Phalange.html&quot; title=&quot;Bouclier phalange&quot;&gt;Bouclier phalange&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;AMH&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Similaire &#224; un &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pavois-(Armure).html&quot; title=&quot;Pavois&quot;&gt;pavois&lt;/a&gt; +2 en &lt;a class=&quot;pagelink&quot; href=&quot;Mat&#233;riaux-Sp&#233;ciaux#Adamantium.html&quot; title=&quot;adamantium&quot;&gt;adamantium&lt;/a&gt;&lt;/i&gt;. Une fois par jour, permet de manifester deux &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Alli&#233;-Spirituel.html&quot; title=&quot;Alli&#233; spirituel&quot;&gt;alli&#233;s spirituels&lt;/a&gt;&lt;/i&gt; qui ne peuvent ni attaquer ni se d&#233;placer au-del&#224; des cases adjacentes au porteur, mais qui ont un bonus d&#39;alt&#233;ration de +4 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt; et le don &lt;a class=&quot;pagelink&quot; href=&quot;Mur-De-Boucliers.html&quot; title=&quot;Mur de boucliers&quot;&gt;Mur de boucliers&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;14 080 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bouclier-Maelstr&#246;m.html&quot; title=&quot;Bouclier maelstr&#246;m&quot;&gt;Bouclier Maelstr&#246;m&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Similaire &#224; un &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;cu-(Armure).html&quot; title=&quot;&#201;cu (bois/acier)&quot;&gt;&#233;cu (acier)&lt;/a&gt; d’&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Attaque.html&quot; title=&quot;attaque (propri&#233;t&#233;)&quot;&gt;attaque&lt;/a&gt; +1&lt;/i&gt;. Lors d’un coup de bouclier, permet au porteur d’effectuer une manœuvre de &lt;a class=&quot;pagelink&quot; href=&quot;Croc-En-Jambe.html&quot; title=&quot;croc-en-jambe&quot;&gt;croc-en-jambe&lt;/a&gt; gratuite sans provoquer d’&lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Attaquedopportunite.html&quot; title=&quot;attaque d&amp;#39;opportunit&#233;&quot;&gt;attaque d’opportunit&#233;&lt;/a&gt; pour la cible. Peut produire 4 litres d’eau fra&#238;che et potable &#224; volont&#233;. Une fois par jour, peut manifester les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouss&#233;e-Hydraulique.html&quot; title=&quot;Pouss&#233;e hydraulique&quot;&gt;pouss&#233;e hydraulique&lt;/a&gt;&lt;/i&gt;.&lt;/td&gt;&lt;td&gt;14 170 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bouclier-Malveillant.html&quot; title=&quot;Bouclier malveillant&quot;&gt;Bouclier malveillant&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;BD&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Similaire &#224; un &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;cu-(Armure).html&quot; title=&quot;&#201;cu (bois/acier)&quot;&gt;&#233;cu en acier&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Miroir.html&quot; title=&quot;miroir (propri&#233;t&#233;)&quot;&gt;miroir&lt;/a&gt; +2&lt;/i&gt;. Trois fois par jour, peut rendre une cr&#233;ature adjacente &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Secou&#233;.html&quot; title=&quot;secou&#233;&quot;&gt;secou&#233;e&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Fi&#233;vreux.html&quot; title=&quot;Fi&#233;vreux&quot;&gt;fi&#233;vreuse&lt;/a&gt; avec une &lt;a class=&quot;pagelink&quot; href=&quot;Regard-(Capacit&#233;).html&quot; title=&quot;Regard (Sur)&quot;&gt;attaque de regard&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;14 170 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bouclier-Volcanique.html&quot; title=&quot;Bouclier volcanique&quot;&gt;Bouclier Volcanique&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Similaire &#224; un &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;cu-(Armure).html&quot; title=&quot;&#201;cu (bois/acier)&quot;&gt;&#233;cu (acier)&lt;/a&gt; d’&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Attaque.html&quot; title=&quot;attaque (propri&#233;t&#233;)&quot;&gt;attaque&lt;/a&gt; +1&lt;/i&gt;. Lors d’un coup de bouclier, est consid&#233;r&#233; comme poss&#233;dant la propri&#233;t&#233; de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armes#Feu.html&quot; title=&quot;feu (propri&#233;t&#233;)&quot;&gt;feu&lt;/a&gt;&lt;/i&gt;. Peut cracher des &lt;a class=&quot;pagelink&quot; href=&quot;Outils-Alchimiques.html#B&#226;ton fumig&#232;ne&quot; title=&quot;Outils alchimiques&quot;&gt;b&#226;tons fumig&#232;nes&lt;/a&gt; qui ne bloquent pas la vision du porteur &#224; volont&#233;. Une fois par jour, peut manifester les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mains-Br&#251;lantes.html&quot; title=&quot;Mains br&#251;lantes&quot;&gt;mains br&#251;lantes&lt;/a&gt;&lt;/i&gt;.&lt;/td&gt;&lt;td&gt;14 170 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bouclier-Des-Temp&#234;tes.html&quot; title=&quot;Bouclier des temp&#234;tes&quot;&gt;Bouclier des Temp&#234;tes&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Similaire &#224; un &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;cu-(Armure).html&quot; title=&quot;&#201;cu (bois/acier)&quot;&gt;&#233;cu (acier)&lt;/a&gt; d’&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Attaque.html&quot; title=&quot;attaque (propri&#233;t&#233;)&quot;&gt;attaque&lt;/a&gt; +1&lt;/i&gt;. Lors d’un coup de bouclier, permet au porteur d’effectuer une manœuvre de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Bousculade.html&quot; title=&quot;bousculade&quot;&gt;bousculade&lt;/a&gt; gratuite sans provoquer d’&lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Attaquedopportunite.html&quot; title=&quot;attaque d&amp;#39;opportunit&#233;&quot;&gt;attaque d’opportunit&#233;&lt;/a&gt; pour la cible. Une fois par jour, peut manifester les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bourrasque.html&quot; title=&quot;Bourrasque&quot;&gt;bourrasque&lt;/a&gt;&lt;/i&gt;.&lt;/td&gt;&lt;td&gt;15 170 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bouclier-Cr&#233;nel&#233;.html&quot; title=&quot;Bouclier cr&#233;nel&#233;&quot;&gt;Bouclier Cr&#233;nel&#233;&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Similaire &#224; un &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pavois-(Armure).html&quot; title=&quot;Pavois&quot;&gt;pavois&lt;/a&gt; +2&lt;/i&gt;. Une fois par jour, peut se transformer en un mur de 30cm d’&#233;paisseur couvrant une superficie de 3m sur 3m avec un sommet cr&#233;nel&#233; et une meurtri&#232;re tous les 1,50m.&lt;/td&gt;&lt;td&gt;16 180 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sceau-Du-Mar&#233;chal-Bouclier.html&quot; title=&quot;Sceau du mar&#233;chal-bouclier&quot;&gt;Sceau du mar&#233;chal-bouclier&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CMy&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Similaire &#224; une &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Targe-(Armure).html&quot; title=&quot;Targe&quot;&gt;targe&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Anti-Projectiles.html&quot; title=&quot;anti-projectiles (propri&#233;t&#233;)&quot;&gt;anti-projectiles&lt;/a&gt; +1&lt;/i&gt;. Lorsque le porteur parvient &#224; parer un projectile avec ce bouclier et au prix d&#39;une utilisation de &lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Pouvoirmythique.html&quot; title=&quot;pouvoir mythique&quot;&gt;pouvoir mythique&lt;/a&gt;, peut le renvoyer sur une cr&#233;ature ciblable avec les m&#234;mes &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jets d’attaque&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#DEGATS&quot; title=&quot;Valeurs de combat&quot;&gt;de d&#233;g&#226;ts&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;17 155 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bouclier-Ail&#233;.html&quot; title=&quot;Bouclier ail&#233;&quot;&gt;Bouclier Ail&#233;&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Similaire &#224; un &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;cu-(Armure).html&quot; title=&quot;&#201;cu (bois/acier)&quot;&gt;&#233;cu (bois)&lt;/a&gt; +3&lt;/i&gt;. Une fois par jour, peut profiter des effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sort-Vol.html&quot; title=&quot;Vol&quot;&gt;vol&lt;/a&gt;&lt;/i&gt; et transporter son porteur (atteignant une charge interm&#233;diaire au-del&#224; de 66,5kg).&lt;/td&gt;&lt;td&gt;17 257 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bouclier-De-Festin-Sanglant.html&quot; title=&quot;Bouclier de festin sanglant&quot;&gt;Bouclier de festin sanglant&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CM&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Similaire &#224; un &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;cu-(Armure).html&quot; title=&quot;&#201;cu (bois/acier)&quot;&gt;&#233;cu (acier)&lt;/a&gt; +2&lt;/i&gt;. Trois fois par jour, peut infliger 1d6 points de d&#233;g&#226;ts et un &lt;a class=&quot;pagelink&quot; href=&quot;Affaiblissement-Temporaire-(Capacit&#233;).html&quot; title=&quot;affaiblissement temporaire&quot;&gt;affaiblissement temporaire&lt;/a&gt; de 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Constitution.html&quot; title=&quot;La Constitution&quot;&gt;Constitution&lt;/a&gt; &#224; une cr&#233;ature &#224; port&#233;e du porteur (en attaquant avec son &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Bonusdebasealattaque.html&quot; title=&quot;BBA&quot;&gt;BBA&lt;/a&gt;). Si le porteur est vampirique, ce pouvoir lui rend 5 points de vie (ou lui en conf&#232;re 5 temporaires pendant 1 heure).&lt;/td&gt;&lt;td&gt;18 770 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bouclier-Des-&#201;boulis.html&quot; title=&quot;Bouclier des &#233;boulis&quot;&gt;Bouclier des &#201;boulis&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Similaire &#224; un &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;cu-(Armure).html&quot; title=&quot;&#201;cu (bois/acier)&quot;&gt;&#233;cu (acier)&lt;/a&gt; d’&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Attaque.html&quot; title=&quot;attaque (propri&#233;t&#233;)&quot;&gt;attaque&lt;/a&gt; +1&lt;/i&gt;. Lors d’un coup de bouclier, peut &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Enchev&#234;tr&#233;.html&quot; title=&quot;Enchev&#234;tr&#233;&quot;&gt;enchev&#234;trer&lt;/a&gt; la cible pendant 1d4 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round(s)&lt;/a&gt;. Une fois par jour, peut &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#P&#233;trifi&#233;.html&quot; title=&quot;P&#233;trifi&#233;&quot;&gt;p&#233;trifier&lt;/a&gt; une cr&#233;ature pendant 1 minute.&lt;/td&gt;&lt;td&gt;19 170 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bouclier-Forteresse.html&quot; title=&quot;Bouclier forteresse&quot;&gt;Bouclier Forteresse&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Similaire &#224; un &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pavois-(Armure).html&quot; title=&quot;Pavois&quot;&gt;pavois&lt;/a&gt; +1&lt;/i&gt;. Peut se transformer en un cube avec des parois de 2,5cm d’&#233;paisseur couvrant la case occup&#233;e par le porteur, &#224; volont&#233;. Ce cube ne laisse rien passer, for&#231;ant les cr&#233;atures &#224; l’int&#233;rieur &#224; retenir leur souffle apr&#232;s 3 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt; pass&#233;s &#224; l’int&#233;rieur.&lt;/td&gt;&lt;td&gt;19 180 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bouclier-Du-Pourfendeur-De-Dracosires.html&quot; title=&quot;Bouclier du pourfendeur de dracosires&quot;&gt;Bouclier du Pourfendeur de Dracosires&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Similaire &#224; un &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;cu-(Armure).html&quot; title=&quot;&#201;cu (bois/acier)&quot;&gt;&#233;cu (acier)&lt;/a&gt; +4&lt;/i&gt;. Conf&#232;re un bonus de +2 aux jets de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;R&#233;flexes&quot;&gt;R&#233;flexes&lt;/a&gt; contre les effets dont l’origine ou le rayonnement ne provient pas de l’espace qu’occupe le porteur, et un bonus de moral de +6 aux jets de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt; contre la capacit&#233; &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sence-Terrifiante-(Capacit&#233;).html&quot; title=&quot;Pr&#233;sence terrifiante (Ext)&quot;&gt;pr&#233;sence terrifiante&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;20 170 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bastion-De-Lh&#233;riti&#232;re.html&quot; title=&quot;Bastion de l&amp;#39;H&#233;riti&#232;re&quot;&gt;Bastion de l&#39;H&#233;riti&#232;re&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CMy&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Similaire &#224; un &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;cu-(Armure).html&quot; title=&quot;&#201;cu (bois/acier)&quot;&gt;&#233;cu en acier&lt;/a&gt; de &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Ralliement.html&quot; title=&quot;ralliement (propri&#233;t&#233;)&quot;&gt;ralliement&lt;/a&gt; +1&lt;/i&gt;. Peut servir de &lt;a class=&quot;pagelink&quot; href=&quot;&#201;quipement-Daventurier.html#Symbole sacr&#233;&quot; title=&quot;&#201;quipement d&amp;#39;aventurier&quot;&gt;symbole sacr&#233;&lt;/a&gt; pour les suivants de la d&#233;esse de la bravoure. R&#233;duit les d&#233;g&#226;ts subits par le porteur de certaines sources mal&#233;fiques. Au prix d&#39;une utilisation de &lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Pouvoirmythique.html&quot; title=&quot;pouvoir mythique&quot;&gt;pouvoir mythique&lt;/a&gt;, les &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#CHATIMENTDUMAL&quot; title=&quot;Le paladin&quot;&gt;ch&#226;timents du Mal&lt;/a&gt; du porteur conf&#232;rent &#224; ses alli&#233;s dans un rayon de 3m leur bonus de parade &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;22 170 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pavois-Desquive-Magique.html&quot; title=&quot;Pavois d’esquive magique&quot;&gt;Pavois d’Esquive Magique&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Similaire &#224; un &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pavois-(Armure).html&quot; title=&quot;Pavois&quot;&gt;pavois&lt;/a&gt; de &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#R&#233;sistance-&#192;-La-Magie-(13).html&quot; title=&quot;r&#233;sistance &#224; la magie 13 (propri&#233;t&#233;)&quot;&gt;r&#233;sistance &#224; la magie (13)&lt;/a&gt; +2&lt;/i&gt;. Conf&#232;re un bonus de r&#233;sistance de +4 aux jets de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;R&#233;flexes&quot;&gt;R&#233;flexes&lt;/a&gt; contre les sorts et les pouvoirs magiques. Une fois par jour, lorsque le porteur r&#233;ussit un tel &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jet de sauvegarde&lt;/a&gt; pour ne subir que la moiti&#233; des d&#233;g&#226;ts d’un effet, il peut n’en subir aucun &#224; la place.&lt;/td&gt;&lt;td&gt;25 180 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lentille-De-La-Sombre-Tapisserie.html&quot; title=&quot;Lentille de la Sombre Tapisserie&quot;&gt;Lentille de la Sombre Tapisserie&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;AMH&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Similaire &#224; un &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;cu-(Armure).html&quot; title=&quot;&#201;cu (bois/acier)&quot;&gt;&#233;cu&lt;/a&gt;&lt;/i&gt; +1 en &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mat&#233;riaux-Sp&#233;ciaux.html#VERREDUVIDE&quot; title=&quot;Les mat&#233;riaux sp&#233;ciaux&quot;&gt;verre du vide&lt;/a&gt;&lt;/i&gt;. Le porteur peut s&#39;infliger 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Affaiblissement-Temporaire-(Capacit&#233;).html&quot; title=&quot;Diminution permanente&quot;&gt;diminution permanente&lt;/a&gt; de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Sagesse.html&quot; title=&quot;La Sagesse&quot;&gt;Sagesse&lt;/a&gt; pour bannir une cr&#233;ature dans la Sombre Tapisserie, l&#39;asphyxiant et lui infligeant des d&#233;g&#226;ts &#224; chaque round.&lt;/td&gt;&lt;td&gt;29 170 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Targe-De-Blocage-&#201;clair.html&quot; title=&quot;Targe de blocage &#233;clair&quot;&gt;Targe de Blocage &#201;clair&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Similaire &#224; une &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Targe-(Armure).html&quot; title=&quot;Targe&quot;&gt;targe&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Anti-Projectiles.html&quot; title=&quot;anti-projectiles (propri&#233;t&#233;)&quot;&gt;anti-projectiles&lt;/a&gt; +3&lt;/i&gt;. Une fois par &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt;, peut augmenter son bonus d’alt&#233;ration de 2 contre une attaque au corps &#224; corps (si l’attaque est bloqu&#233;e, la propri&#233;t&#233; &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Anti-Projectiles.html&quot; title=&quot;anti-projectiles (propri&#233;t&#233;)&quot;&gt;anti-projectiles&lt;/a&gt;&lt;/i&gt; est inutilisable pendant 1 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt;).&lt;/td&gt;&lt;td&gt;36 155 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bouclier-Agressif.html&quot; title=&quot;Bouclier agressif&quot;&gt;Bouclier Agressif&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Similaire &#224; un &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;cu-(Armure).html&quot; title=&quot;&#201;cu (bois/acier)&quot;&gt;&#233;cu (acier)&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Anim&#233;e.html&quot; title=&quot;anim&#233;e (propri&#233;t&#233;)&quot;&gt;anim&#233;&lt;/a&gt; d’&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Attaque.html&quot; title=&quot;attaque (propri&#233;t&#233;)&quot;&gt;attaque&lt;/a&gt; +1&lt;/i&gt;. Apr&#232;s le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt; d’animation, peut effectuer un coup de bouclier contre une cr&#233;ature &#224; port&#233;e de l’activateur &#224; chaque &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt; (consid&#233;rant qu’il poss&#232;de toutes les am&#233;liorations de coup de bouclier de celui-ci, sans lui faire perdre son bonus de bouclier &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt; ni lui imposer de malus aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jets d’attaque&lt;/a&gt;).&lt;/td&gt;&lt;td&gt;36 170 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pavois-De-Force.html&quot; title=&quot;Pavois de force&quot;&gt;Pavois de Force&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Similaire &#224; un &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pavois-(Armure).html&quot; title=&quot;Pavois&quot;&gt;pavois&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Spectrale.html&quot; title=&quot;spectrale (propri&#233;t&#233; armure)&quot;&gt;spectral&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Anti-Projectiles.html&quot; title=&quot;anti-projectiles (propri&#233;t&#233;)&quot;&gt;anti-projectiles&lt;/a&gt; +1 en &lt;a class=&quot;pagelink&quot; href=&quot;Mat&#233;riaux-Sp&#233;ciaux#Mithral.html&quot; title=&quot;mithral&quot;&gt;mithral&lt;/a&gt;&lt;/i&gt;. Permet d’utiliser la propri&#233;t&#233; &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Anti-Projectiles.html&quot; title=&quot;anti-projectiles (propri&#233;t&#233;)&quot;&gt;anti-projectiles&lt;/a&gt;&lt;/i&gt; pour d&#233;vier les rayons magiques et les attaques de contact &#224; distance avec un &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; plus &#233;lev&#233; (mais seulement un rayon ou une attaque de la m&#234;me source &#224; chaque &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt;).&lt;/td&gt;&lt;td&gt;46 030 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bouclier-Phagocyte.html&quot; title=&quot;Bouclier phagocyte&quot;&gt;Bouclier Phagocyte&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Similaire &#224; un &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;cu-(Armure).html&quot; title=&quot;&#201;cu (bois/acier)&quot;&gt;&#233;cu (acier)&lt;/a&gt; +1&lt;/i&gt;. Une fois tous les deux jours, peut d&#233;sint&#233;grer un objet (comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;sint&#233;gration.html&quot; title=&quot;D&#233;sint&#233;gration&quot;&gt;d&#233;sint&#233;gration&lt;/a&gt;&lt;/i&gt;) au touch&#233;.&lt;/td&gt;&lt;td&gt;50 170 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bouclier-De-L&#233;lys&#233;e.html&quot; title=&quot;Bouclier de l’&#201;lys&#233;e&quot;&gt;Bouclier de l’&#201;lys&#233;e&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E, MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Similaire &#224; un &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pavois-(Armure).html&quot; title=&quot;Pavois&quot;&gt;pavois&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Spectrale.html&quot; title=&quot;spectrale (propri&#233;t&#233; armure)&quot;&gt;spectral&lt;/a&gt; +2&lt;/i&gt;. Immunise le porteur contre la capacit&#233; cr&#233;ation de rejetons des morts-vivants. Une fois par jour, peut annuler une attaque d’&lt;a class=&quot;pagelink&quot; href=&quot;Absorption-D&#233;nergie-(Capacit&#233;).html&quot; title=&quot;Absorption d’&#233;nergie (Sur)&quot;&gt;absorption d’&#233;nergie&lt;/a&gt; d’&lt;a class=&quot;pagelink&quot; href=&quot;Affaiblissement-Temporaire-(Capacit&#233;).html&quot; title=&quot;Affaiblissement temporaire (Ext ou Sur)&quot;&gt;affaiblissement temporaire&lt;/a&gt; ou de &lt;a class=&quot;pagelink&quot; href=&quot;Affaiblissement-Temporaire-(Capacit&#233;).html&quot; title=&quot;Affaiblissement temporaire (Ext ou Sur)&quot;&gt;diminution permanente&lt;/a&gt; de caract&#233;ristique inflig&#233;e par un mort-vivant. Une fois par jour, peut &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Paniqu&#233;.html&quot; title=&quot;Paniqu&#233;&quot;&gt;paniquer&lt;/a&gt; les morts-vivants dans un rayon de 9m autour du porteur (comme avec &lt;a class=&quot;pagelink&quot; href=&quot;Renvoi-Des-Morts-Vivants.html&quot; title=&quot;Renvoi des morts-vivants&quot;&gt;Renvoi des morts-vivants&lt;/a&gt;).&lt;/td&gt;&lt;td&gt;52 620 po&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/center&gt;
